          scopes, client_credentials_scopes, redirect_uris, token_endpoint_auth_method,
          grant_types, response_types, require_pkce, application_type, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
